struct StdVideoDecodeH265PictureInfoFlags
    data::NTuple{4, UInt8}
end

function Base.getproperty(x::Ptr{StdVideoDecodeH265PictureInfoFlags}, f::Symbol)
    f === :IrapPicFlag && return (Ptr{UInt32}(x + 0), 0, 1)
    f === :IdrPicFlag && return (Ptr{UInt32}(x + 0), 1, 1)
    f === :IsReference && return (Ptr{UInt32}(x + 0), 2, 1)
    f === :short_term_ref_pic_set_sps_flag && return (Ptr{UInt32}(x + 0), 3, 1)
    return getfield(x, f)
end

function Base.getproperty(x::StdVideoDecodeH265PictureInfoFlags, f::Symbol)
    r = Ref{StdVideoDecodeH265PictureInfoFlags}(x)
    ptr = Base.unsafe_convert(Ptr{StdVideoDecodeH265PictureInfoFlags}, r)
    fptr = getproperty(ptr, f)
    begin
        if fptr isa Ptr
            return GC.@preserve(r, unsafe_load(fptr))
        else
            (baseptr, offset, width) = fptr
            ty = eltype(baseptr)
            baseptr32 = convert(Ptr{UInt32}, baseptr)
            u64 = GC.@preserve(r, unsafe_load(baseptr32))
            if offset + width > 32
                u64 |= GC.@preserve(r, unsafe_load(baseptr32 + 4)) << 32
            end
            u64 = u64 >> offset & (1 << width - 1)
            return u64 % ty
        end
    end
end

function Base.setproperty!(x::Ptr{StdVideoDecodeH265PictureInfoFlags}, f::Symbol, v)
    fptr = getproperty(x, f)
    if fptr isa Ptr
        unsafe_store!(getproperty(x, f), v)
    else
        (baseptr, offset, width) = fptr
        baseptr32 = convert(Ptr{UInt32}, baseptr)
        u64 = unsafe_load(baseptr32)
        straddle = offset + width > 32
        if straddle
            u64 |= unsafe_load(baseptr32 + 4) << 32
        end
        mask = 1 << width - 1
        u64 &= ~(mask << offset)
        u64 |= (unsigned(v) & mask) << offset
        unsafe_store!(baseptr32, u64 & typemax(UInt32))
        if straddle
            unsafe_store!(baseptr32 + 4, u64 >> 32)
        end
    end
end

function Base.propertynames(x::StdVideoDecodeH265PictureInfoFlags, private::Bool = false)
    (:IrapPicFlag, :IdrPicFlag, :IsReference, :short_term_ref_pic_set_sps_flag, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

function StdVideoDecodeH265PictureInfoFlags(IrapPicFlag::UInt32, IdrPicFlag::UInt32, IsReference::UInt32, short_term_ref_pic_set_sps_flag::UInt32)
    ref = Ref{StdVideoDecodeH265PictureInfoFlags}()
    ptr = Base.unsafe_convert(Ptr{StdVideoDecodeH265PictureInfoFlags}, ref)
    ptr.IrapPicFlag = IrapPicFlag
    ptr.IdrPicFlag = IdrPicFlag
    ptr.IsReference = IsReference
    ptr.short_term_ref_pic_set_sps_flag = short_term_ref_pic_set_sps_flag
    ref[]
end

struct StdVideoDecodeH265PictureInfo
    data::NTuple{40, UInt8}
end

function Base.getproperty(x::Ptr{StdVideoDecodeH265PictureInfo}, f::Symbol)
    f === :flags && return Ptr{StdVideoDecodeH265PictureInfoFlags}(x + 0)
    f === :sps_video_parameter_set_id && return Ptr{UInt8}(x + 4)
    f === :pps_seq_parameter_set_id && return Ptr{UInt8}(x + 5)
    f === :pps_pic_parameter_set_id && return Ptr{UInt8}(x + 6)
    f === :NumDeltaPocsOfRefRpsIdx && return Ptr{UInt8}(x + 7)
    f === :PicOrderCntVal && return Ptr{Int32}(x + 8)
    f === :NumBitsForSTRefPicSetInSlice && return Ptr{UInt16}(x + 12)
    f === :reserved && return Ptr{UInt16}(x + 14)
    f === :RefPicSetStCurrBefore && return Ptr{NTuple{8, UInt8}}(x + 16)
    f === :RefPicSetStCurrAfter && return Ptr{NTuple{8, UInt8}}(x + 24)
    f === :RefPicSetLtCurr && return Ptr{NTuple{8, UInt8}}(x + 32)
    return getfield(x, f)
end

function Base.getproperty(x::StdVideoDecodeH265PictureInfo, f::Symbol)
    r = Ref{StdVideoDecodeH265PictureInfo}(x)
    ptr = Base.unsafe_convert(Ptr{StdVideoDecodeH265PictureInfo}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{StdVideoDecodeH265PictureInfo}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
