    f === :mono_chrome && return (Ptr{UInt32}(x + 0), 0, 1)
    f === :color_range && return (Ptr{UInt32}(x + 0), 1, 1)
    f === :separate_uv_delta_q && return (Ptr{UInt32}(x + 0), 2, 1)
