    f === :refresh_frame_context && return (Ptr{UInt32}(x + 0), 3, 1)
    f === :frame_parallel_decoding_mode && return (Ptr{UInt32}(x + 0), 4, 1)
    f === :segmentation_enabled && return (Ptr{UInt32}(x + 0), 5, 1)
    f === :show_frame && return (Ptr{UInt32}(x + 0), 6, 1)
    f === :UsePrevFrameMvs && return (Ptr{UInt32}(x + 0), 7, 1)
    f === :reserved && return (Ptr{UInt32}(x + 0), 8, 24)
    return getfield(x, f)
