struct VkPerformanceValueDataINTEL
    data::NTuple{8, UInt8}
end

function Base.getproperty(x::Ptr{VkPerformanceValueDataINTEL}, f::Symbol)
    f === :value32 && return Ptr{UInt32}(x + 0)
    f === :value64 && return Ptr{UInt64}(x + 0)
    f === :valueFloat && return Ptr{Cfloat}(x + 0)
    f === :valueBool && return Ptr{VkBool32}(x + 0)
    f === :valueString && return Ptr{Ptr{Cchar}}(x + 0)
    return getfield(x, f)
end

function Base.getproperty(x::VkPerformanceValueDataINTEL, f::Symbol)
    r = Ref{VkPerformanceValueDataINTEL}(x)
    ptr = Base.unsafe_convert(Ptr{VkPerformanceValueDataINTEL}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{VkPerformanceValueDataINTEL}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::VkPerformanceValueDataINTEL, private::Bool = false)
    (:value32, :value64, :valueFloat, :valueBool, :valueString, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

const __U_VkPerformanceValueDataINTEL = Union{UInt32, UInt64, Cfloat, VkBool32, Ptr{Cchar}}

function VkPerformanceValueDataINTEL(val::__U_VkPerformanceValueDataINTEL)
    ref = Ref{VkPerformanceValueDataINTEL}()
    ptr = Base.unsafe_convert(Ptr{VkPerformanceValueDataINTEL}, ref)
    if val isa UInt32
        ptr.value32 = val
    elseif val isa UInt64
        ptr.value64 = val
    elseif val isa Cfloat
        ptr.valueFloat = val
    elseif val isa VkBool32
        ptr.valueBool = val
    elseif val isa Ptr{Cchar}
        ptr.valueString = val
    end
    ref[]
end

struct VkPerformanceValueINTEL
    data::NTuple{16, UInt8}
end

function Base.getproperty(x::Ptr{VkPerformanceValueINTEL}, f::Symbol)
    f === :type && return Ptr{VkPerformanceValueTypeINTEL}(x + 0)
    f === :data && return Ptr{VkPerformanceValueDataINTEL}(x + 8)
    return getfield(x, f)
end

function Base.getproperty(x::VkPerformanceValueINTEL, f::Symbol)
    r = Ref{VkPerformanceValueINTEL}(x)
    ptr = Base.unsafe_convert(Ptr{VkPerformanceValueINTEL}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{VkPerformanceValueINTEL}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::VkPerformanceValueINTEL, private::Bool = false)
    (:type, :data, if private
            fieldnames(typeof(x))
