            ()
        end...)
end

function VkPerformanceValueINTEL(type::VkPerformanceValueTypeINTEL, data::VkPerformanceValueDataINTEL)
    ref = Ref{VkPerformanceValueINTEL}()
    ptr = Base.unsafe_convert(Ptr{VkPerformanceValueINTEL}, ref)
    ptr.type = type
    ptr.data = data
    ref[]
end

