const __U_VkDescriptorDataEXT = Union{Ptr{VkSampler}, Ptr{VkDescriptorImageInfo}, Ptr{VkDescriptorImageInfo}, Ptr{VkDescriptorImageInfo}, Ptr{VkDescriptorImageInfo}, Ptr{VkDescriptorAddressInfoEXT}, Ptr{VkDescriptorAddressInfoEXT}, Ptr{VkDescriptorAddressInfoEXT}, Ptr{VkDescriptorAddressInfoEXT}, VkDeviceAddress}

function VkDescriptorDataEXT(val::__U_VkDescriptorDataEXT)
    ref = Ref{VkDescriptorDataEXT}()
    ptr = Base.unsafe_convert(Ptr{VkDescriptorDataEXT}, ref)
    if val isa Ptr{VkSampler}
        ptr.pSampler = val
    elseif val isa Ptr{VkDescriptorImageInfo}
        ptr.pCombinedImageSampler = val
    elseif val isa Ptr{VkDescriptorImageInfo}
        ptr.pInputAttachmentImage = val
    elseif val isa Ptr{VkDescriptorImageInfo}
        ptr.pSampledImage = val
    elseif val isa Ptr{VkDescriptorImageInfo}
        ptr.pStorageImage = val
    elseif val isa Ptr{VkDescriptorAddressInfoEXT}
        ptr.pUniformTexelBuffer = val
    elseif val isa Ptr{VkDescriptorAddressInfoEXT}
        ptr.pStorageTexelBuffer = val
    elseif val isa Ptr{VkDescriptorAddressInfoEXT}
        ptr.pUniformBuffer = val
    elseif val isa Ptr{VkDescriptorAddressInfoEXT}
        ptr.pStorageBuffer = val
    elseif val isa VkDeviceAddress
        ptr.accelerationStructure = val
    end
    ref[]
end

