function Base.getproperty(x::Ptr{VkConvertCooperativeVectorMatrixInfoNV}, f::Symbol)
    f === :sType && return Ptr{VkStructureType}(x + 0)
    f === :pNext && return Ptr{Ptr{Cvoid}}(x + 8)
    f === :srcSize && return Ptr{Csize_t}(x + 16)
    f === :srcData && return Ptr{VkDeviceOrHostAddressConstKHR}(x + 24)
    f === :pDstSize && return Ptr{Ptr{Csize_t}}(x + 32)
    f === :dstData && return Ptr{VkDeviceOrHostAddressKHR}(x + 40)
    f === :srcComponentType && return Ptr{VkComponentTypeKHR}(x + 48)
    f === :dstComponentType && return Ptr{VkComponentTypeKHR}(x + 52)
    f === :numRows && return Ptr{UInt32}(x + 56)
    f === :numColumns && return Ptr{UInt32}(x + 60)
    f === :srcLayout && return Ptr{VkCooperativeVectorMatrixLayoutNV}(x + 64)
    f === :srcStride && return Ptr{Csize_t}(x + 72)
    f === :dstLayout && return Ptr{VkCooperativeVectorMatrixLayoutNV}(x + 80)
    f === :dstStride && return Ptr{Csize_t}(x + 88)
    return getfield(x, f)
end

function Base.getproperty(x::VkConvertCooperativeVectorMatrixInfoNV, f::Symbol)
    r = Ref{VkConvertCooperativeVectorMatrixInfoNV}(x)
    ptr = Base.unsafe_convert(Ptr{VkConvertCooperativeVectorMatrixInfoNV}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{VkConvertCooperativeVectorMatrixInfoNV}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::VkConvertCooperativeVectorMatrixInfoNV, private::Bool = false)
    (:sType, :pNext, :srcSize, :srcData, :pDstSize, :dstData, :srcComponentType, :dstComponentType, :numRows, :numColumns, :srcLayout, :srcStride, :dstLayout, :dstStride, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

function VkConvertCooperativeVectorMatrixInfoNV(sType::VkStructureType, pNext::Ptr{Cvoid}, srcSize::Csize_t, srcData::VkDeviceOrHostAddressConstKHR, pDstSize::Ptr{Csize_t}, dstData::VkDeviceOrHostAddressKHR, srcComponentType::VkComponentTypeKHR, dstComponentType::VkComponentTypeKHR, numRows::UInt32, numColumns::UInt32, srcLayout::VkCooperativeVectorMatrixLayoutNV, srcStride::Csize_t, dstLayout::VkCooperativeVectorMatrixLayoutNV, dstStride::Csize_t)
    ref = Ref{VkConvertCooperativeVectorMatrixInfoNV}()
    ptr = Base.unsafe_convert(Ptr{VkConvertCooperativeVectorMatrixInfoNV}, ref)
    ptr.sType = sType
    ptr.pNext = pNext
    ptr.srcSize = srcSize
    ptr.srcData = srcData
    ptr.pDstSize = pDstSize
    ptr.dstData = dstData
    ptr.srcComponentType = srcComponentType
    ptr.dstComponentType = dstComponentType
    ptr.numRows = numRows
    ptr.numColumns = numColumns
    ptr.srcLayout = srcLayout
    ptr.srcStride = srcStride
    ptr.dstLayout = dstLayout
    ptr.dstStride = dstStride
    ref[]
end

